var EXTRA=[{dot:"gray",j:"Cureus",h:"Pseudoaneurisma dopo artroscopia del ginocchio: i casi pubblicati, il popliteo è il vaso più colpito",v:"Revisione sistematica di segnalazioni di casi: la diagnosi spesso è tardiva perché somiglia a emartro o gonfiore; non stima incidenza né rischio, ricorda quando pensare all'imaging vascolare.",pmid:'42894765',doi:'10.7759/cureus.116501',temi:["artroscopia", "complicanze", "pseudoaneurisma", "lesione vascolare"]},{dot:"gray",j:"J Exp Orthop",h:"Hockey professionistico: dopo il LCA la prestazione scende rispetto ai controlli",v:"Studio caso-controllo su giocatori della NHL con statistiche avanzate; misura il rendimento e non il ginocchio, su atleti selezionati.",pmid:'42899301',doi:'10.1002/jeo2.70588',temi:["LCA", "rientro allo sport", "hockey", "prestazione"]},{dot:"gray",j:"J Exp Orthop",h:"LCA deficitario cronico: più lesioni del menisco mediale alla risonanza",v:"Revisione sistematica di studi di livello II-IV con casistiche eterogenee: il menisco mediale e la sublussazione tibiale anteriore pesano di più con il tempo; non indica quando operare.",pmid:'42899038',doi:'10.1002/jeo2.70696',temi:["LCA", "menisco mediale", "risonanza", "tempo dall'infortunio"]},{dot:"gray",j:"Asia Pac J Sports Med Arthrosc Rehabil Technol",h:"Osteotomia tibiale alta di apertura: togliere il mezzo di sintesi riduce l'irritazione",v:"Coorte prospettica senza controllo e con controllo a 3 mesi; i pazienti sono soddisfatti ma il dolore residuo condiziona il giudizio.",pmid:'42898098',doi:'10.1016/j.asmart.2026.09.003',temi:["osteotomia tibiale alta", "rimozione impianto", "soddisfazione", "complicanze"]},{dot:"gray",j:"Rev Esp Cir Ortop Traumatol",h:"Segno di Akmese per la radice mediale posteriore: accuratezza alta in una coorte peruviana",v:"Test clinico valutato su pazienti già destinati all'artroscopia, quindi selezionati; gli autori lo vedono come aggiunta e non come sostituto della risonanza.",pmid:'42901444',doi:'10.1016/j.recot.2026.10.010',temi:["radice meniscale", "menisco mediale", "esame clinico", "diagnosi"]},{dot:"gray",j:"J Exp Orthop",h:"Estrusione del menisco mediale: dipende dal tipo di lesione, radice e complesse la aumentano",v:"Misure in risonanza su ginocchi con e senza artrosi, livello IV e trasversale; si lega alla tensione sull'estrusione ma non ha esiti clinici.",pmid:'42899283',doi:'10.1002/jeo2.70686',temi:["estrusione meniscale", "radice meniscale", "risonanza", "artrosi"]},{dot:"gray",j:"Acta Orthop Traumatol Turc",h:"MPFL nell'osteogenesi imperfetta: quadricipite peduncolato senza tunnel nella rotula",v:"Caso singolo con tre anni di controllo: idea tecnica per ossa fragili, senza alcun valore statistico.",pmid:'42897817',doi:'10.5152/j.aott.2026.25829',temi:["MPFL", "tendine quadricipitale", "adolescenti", "instabilità rotulea"]},{dot:"gray",j:"Med Sci Sports Exerc",h:"Calciatrici d'élite: più interventi in carriera, meno funzione del ginocchio dopo il ritiro",v:"Studio trasversale con questionario anonimo; correlazioni deboli o moderate, coorte quasi tutta bianca e collegiale, associazione e non causa.",pmid:'42900791',doi:'10.1249/MSS.0000000000004196',temi:["LCA", "calcio femminile", "lungo termine", "chirurgia del ginocchio"]},{dot:"gray",j:"BMC Musculoskelet Disord",h:"Infezione dopo osteotomia attorno al ginocchio: pelle, fegato e calo di emoglobina",v:"Coorte retrospettiva multicentrica con pochi eventi; i fattori sono ipotesi da confermare.",pmid:'42897581',doi:'10.1186/s12891-026-10277-2',temi:["osteotomia", "infezione", "fattori di rischio", "reintervento"]},{dot:"gray",j:"Skeletal Radiol",h:"Maltracking rotuleo: sequenza di risonanza dinamica con contrazione del quadricipite",v:"Fattibile e ben tollerata; la distanza TT-TG aumenta di più nei pazienti, ma il valore aggiunto sulla risonanza statica non è confermato statisticamente.",pmid:'42895634',doi:'10.1007/s00256-026-05400-2',temi:["instabilità rotulea", "TT-TG", "risonanza dinamica", "maltracking"]},{dot:"gray",j:"Indian J Orthop",h:"LCA rotto trattato con cellule dal sangue e PRP: serie preliminare senza controllo",v:"Serie retrospettiva di una sola sede e senza gruppo di confronto: punteggi alti, ma non dice se il legamento guarisca; gli autori chiedono studi controllati.",pmid:'42894546',doi:'10.1007/s43465-026-01904-0',temi:["LCA", "biologici", "PRP", "trattamento non chirurgico"]},{dot:"gray",j:"Cardiovasc Intervent Radiol",h:"Embolizzazione genicolare in Germania: adozione rapida e pochi eventi segnalati",v:"Registro nazionale di qualità, descrittivo: non è pensato per sorvegliare le complicanze e non confronta con altre cure.",pmid:'42897320',doi:'10.1007/s00270-026-04657-3',temi:["embolizzazione genicolare", "artrosi", "registro", "radiologia interventistica"]}];
var SCOPERTE=[{t:"Robot in sala in Germania: l'artrosi del ginocchio diventa la seconda diagnosi dopo la prostata",v:"Serie storica nazionale dei codici ospedalieri 2019-2025 (J Robot Surg): i casi con robot crescono in tutti i campi e la gonartrosi sale al secondo posto. Vale la deviazione perché misura l'adozione reale fuori dagli studi; è descrittiva, non dice nulla su esiti né su quale sistema.",pmid:'42900265',doi:'10.1007/s11701-026-04084-z',temi:["protesi robotica", "adozione", "Germania", "sanità pubblica"]},{t:"La linea articolare orizzontale non è per forza l'obiettivo: un modello matematico del ginocchio",v:"Modello geometrico a due dimensioni (KSSTA, livello V): femore e tibia pesano in modo simile sull'orientamento della linea articolare, e l'allineamento complessivo da solo non lo prevede. Vale la deviazione perché tocca il bersaglio di osteotomie e protesi; è un modello e non misura pazienti.",pmid:'42897439',doi:'10.1002/ksa.70653',temi:["linea articolare", "allineamento", "osteotomia", "biomeccanica"]},{t:"Età ossea letta sulla risonanza del ginocchio: un indice coreano a due misure",v:"Studio di sviluppo e validazione su RM del ginocchio di soggetti fino a 18 anni (Seul): la somma degli intervalli fra metafisi ed epifisi ossificata di femore e tibia stima l'età con buon accordo nel gruppo di validazione. Vale la deviazione perché la maturità scheletrica decide le scelte nel LCA dell'adolescente; è un metodo diagnostico, non dice nulla sull'esito chirurgico.",pmid:'42895227',doi:'10.1097/BPO.0000000000003501',temi:["maturità scheletrica", "adolescenti", "risonanza", "Corea"]}];
var SOC={"1": {"video": "Menisco e crociato operati insieme: conta se la sutura della radice passa dallo stesso tunnel del legamento? Uno studio di Chennai, pubblicato sul Journal of Experimental Orthopaedics, ha confrontato 50 pazienti: in 24 le suture della radice laterale sono passate nel tunnel del crociato, in 26 da un tunnel separato.\n\nDopo due anni punteggi e stabilità erano simili. Con un tunnel solo l'intervento è durato circa 24 minuti in meno; il menisco era guarito del tutto in 16 casi su 24 contro 21 su 26.\n\nLo studio guarda al passato, i gruppi sono piccoli e il legamento era sempre ricostruito con i tendini della coscia: simile non vuol dire uguale.\nFonte: PubMed, PMID 42898998.", "linkedin": "Radice laterale con il LCA: tunnel tibiale condiviso o separato? Coorte retrospettiva di Chennai su 50 pazienti (Journal of Experimental Orthopaedics, 2026): a 2 anni stessi punteggi e stabilità, 24 minuti in meno con il tunnel condiviso, guarigione completa alla RM in 16 casi su 24 contro 21 su 26.\n\nIl limite: gruppi di 24 e 26, un solo chirurgo, innesto hamstring; comparabile non significa equivalente.\nFonte: PubMed, PMID 42898998.", "instagram": "Menisco e crociato insieme\n\nSuture della radice nel tunnel del crociato o in uno a parte? A due anni risultati simili; con un tunnel solo, 24 minuti in meno.\n\nStudio sul passato su 50 pazienti: simile non vuol dire uguale.\nFonte: PubMed, PMID 42898998.", "pazienti": "Menisco e crociato operati insieme: un tunnel in meno. In uno studio su 50 persone, il menisco esterno è stato fissato passando dallo stesso tunnel del legamento oppure da un tunnel a parte.\n\nDopo due anni ginocchio stabile e punteggi simili nei due gruppi; con un tunnel solo l'intervento è durato circa 24 minuti in meno.\n\nLo studio guarda al passato e riguarda pochi pazienti: la scelta della tecnica spetta al chirurgo, caso per caso.\nFonte: PubMed, PMID 42898998."}};
var SOCV={"1": {"video": {"chir": ["Radice posteriore laterale con LCA, tunnel tibiale condiviso o separato? Coorte retrospettiva di Chennai sul Journal of Experimental Orthopaedics, un solo chirurgo, 50 LCA con semitendinoso e gracile: 24 con tunnel condiviso, 26 con tunnel separato, follow-up minimo di 2 anni.", "Tempo operatorio 73,50 ± 8,51 contro 97,00 ± 8,39 minuti, p<0,001. Lysholm 91,50 ± 3,01 contro 91,35 ± 3,03; IKDC 90,52 ± 2,72 contro 89,67 ± 3,07. Guarigione completa alla RM 16/24 contro 21/26, p=0,231; estrusione ridotta di 2,14 ± 0,35 contro 2,01 ± 0,35 mm, p=0,181.", "Limiti: retrospettivo, 24 e 26 pazienti, comparabile non è equivalente: mancata guarigione completa RR 1,73, IC 95% 0,66-4,57. Radice laterale e innesto hamstring.\nFonte: PubMed, PMID 42898998."], "misto": ["Menisco e crociato operati insieme: conta se la sutura della radice passa dallo stesso tunnel del legamento? Uno studio di Chennai, sul Journal of Experimental Orthopaedics, ha confrontato 50 pazienti: in 24 le suture sono passate nel tunnel del crociato, in 26 da un tunnel separato.", "Dopo due anni punteggi e stabilità erano simili. Con un tunnel solo l'intervento è durato circa 24 minuti in meno; il menisco era guarito del tutto in 16 casi su 24 contro 21 su 26.", "Lo studio guarda al passato, i gruppi sono piccoli e il legamento era sempre ricostruito con i tendini della coscia: simile non vuol dire uguale.\nFonte: PubMed, PMID 42898998."], "pazienti": ["Menisco e crociato operati insieme: un tunnel in meno. In uno studio su 50 persone, il menisco esterno è stato fissato passando dallo stesso tunnel del legamento oppure da un tunnel a parte.", "Dopo due anni ginocchio stabile e punteggi simili nei due gruppi; con un tunnel solo l'intervento è durato circa 24 minuti in meno.", "Lo studio guarda al passato e riguarda pochi pazienti: la scelta della tecnica spetta al chirurgo, caso per caso.\nFonte: PubMed, PMID 42898998."]}, "linkedin": {"chir": ["Radice laterale con LCA, tunnel tibiale condiviso contro separato (J Exp Orthop, 2026). Coorte retrospettiva, 50 pazienti, semitendinoso e gracile, minimo 2 anni; tempo operatorio 73,50 ± 8,51 contro 97,00 ± 8,39 minuti (p<0,001).", "Lysholm 91,50 ± 3,01 contro 91,35 ± 3,03; IKDC 90,52 ± 2,72 contro 89,67 ± 3,07; guarigione completa 16/24 contro 21/26 (p=0,231); estrusione ridotta di 2,14 contro 2,01 mm (p=0,181).", "Limiti: retrospettivo, un chirurgo, gruppi di 24 e 26; mancata guarigione completa RR 1,73 (IC 95% 0,66-4,57).\nFonte: PubMed, PMID 42898998."], "misto": ["Radice laterale con il LCA: tunnel condiviso o separato? Coorte retrospettiva di Chennai su 50 pazienti (Journal of Experimental Orthopaedics, 2026): a 2 anni stessi punteggi e stabilità, 24 minuti in meno con il tunnel condiviso.", "Il menisco era guarito del tutto in 16 casi su 24 con il tunnel condiviso e in 21 su 26 con il tunnel separato; la differenza non è significativa, ma i gruppi sono piccoli.", "Il limite: studio sul passato di un solo chirurgo, con tendini della coscia; comparabile non significa equivalente.\nFonte: PubMed, PMID 42898998."], "pazienti": ["Menisco e crociato operati insieme: uno studio su 50 pazienti ha confrontato due modi di fissare l'attacco posteriore del menisco esterno, dallo stesso tunnel del legamento o da un tunnel a parte.", "Dopo due anni risultati simili nei due gruppi, con circa 24 minuti in meno di intervento quando il tunnel era uno solo.", "Lo studio guarda al passato e riguarda pochi pazienti: se ne parla con il chirurgo.\nFonte: PubMed, PMID 42898998."]}, "instagram": {"chir": ["Radice laterale e LCA: tunnel condiviso o separato", "Tempo 73,50 contro 97,00 minuti (p<0,001); a 2 anni Lysholm 91,50 contro 91,35, guarigione completa 16/24 contro 21/26.", "Retrospettivo, 24 e 26 pazienti: comparabile non è equivalente.\nFonte: PubMed, PMID 42898998."], "misto": ["Menisco e crociato insieme", "Suture della radice nel tunnel del crociato o in uno a parte: a due anni risultati simili, 24 minuti in meno con un tunnel solo.", "Studio sul passato su 50 pazienti: simile non vuol dire uguale.\nFonte: PubMed, PMID 42898998."], "pazienti": ["Menisco e crociato, un tunnel in meno", "Passare dallo stesso tunnel del legamento o da uno a parte: dopo due anni risultati simili in 50 persone.", "Studio sul passato e su pochi pazienti. Se ne parla con il chirurgo.\nFonte: PubMed, PMID 42898998."]}, "reel": {"chir": ["Radice laterale con LCA: tunnel condiviso", "73,5 contro 97 minuti, esiti simili a 2 anni (J Exp Orthop).", "Retrospettivo, 24 e 26 pazienti.\nFonte: PubMed, PMID 42898998."], "misto": ["Menisco e crociato: un tunnel solo", "Intervento più breve di circa 24 minuti, risultati simili a due anni.", "Studio sul passato, pochi pazienti.\nFonte: PubMed, PMID 42898998."], "pazienti": ["Menisco e crociato, un tunnel in meno", "Risultati simili dopo due anni, intervento più breve.", "Studio piccolo sul passato. Se ne parla con il chirurgo.\nFonte: PubMed, PMID 42898998."]}}};
var TAGS={"1": {"linkedin": "#Ortopedia #Ginocchio #MedicinaDelloSport", "instagram": "#ortopedia #ginocchio #menisco #legamentocrociato #chirurgiadelginocchio #medicinadellosport #riabilitazione #ortopediaticino #ticino #medicinabasatasulleprove #salute", "kw": "menisco, legamento crociato anteriore, radice del menisco, ginocchio, chirurgia artroscopica"}};
var NLB={"1": {"prof": ["Radice laterale con LCA: tunnel condiviso e separato comparabili a 2 anni, 24 minuti in meno", "Coorte retrospettiva di un chirurgo (J Exp Orthop, 2026; 50 LCA con semitendinoso e gracile e sutura transtibiale della radice laterale: 24 tunnel del LCA condiviso, 26 separato). Tempo operatorio 73,50 ± 8,51 contro 97,00 ± 8,39 minuti (p<0,001); a 2 anni Lysholm 91,50 ± 3,01 contro 91,35 ± 3,03, IKDC 90,52 ± 2,72 contro 89,67 ± 3,07, guarigione alla RM completa in 16/24 contro 21/26 (p=0,231), estrusione ridotta di 2,14 ± 0,35 contro 2,01 ± 0,35 mm.", "Nota critica: 24 e 26 pazienti, 'comparabile' non è equivalenza (guarigione non completa RR 1,73; IC 95% 0,66-4,57); innesto hamstring e radice laterale."], "mix": ["Menisco e crociato operati insieme: due modi di fissare la radice, risultati simili a 2 anni", "In uno studio retrospettivo di un solo chirurgo su 50 pazienti operati di legamento crociato anteriore con rottura della radice posteriore del menisco laterale, la sutura è stata fissata o nello stesso tunnel del legamento o in un tunnel a parte. A 2 anni i punteggi e la stabilità erano simili; l'intervento col tunnel condiviso era più breve di circa 24 minuti, e il menisco era guarito del tutto in 16 casi su 24 contro 21 su 26.", "Nota sul limite: i gruppi sono piccoli e lo studio guarda al passato; non dimostra che i due metodi siano equivalenti."], "paz": ["Menisco e crociato operati insieme: un tunnel in meno, risultati simili in uno studio piccolo", "In uno studio su 50 persone operate al legamento crociato anteriore e con una lesione dell'attacco posteriore del menisco esterno, il chirurgo ha fissato il menisco o passando dallo stesso tunnel del legamento o da un tunnel a parte. Dopo 2 anni ginocchio stabile e punteggi simili nei due gruppi; con un tunnel solo l'intervento è durato circa 24 minuti in meno.", "Lo studio guarda al passato e riguarda pochi pazienti: la scelta della tecnica spetta al chirurgo, caso per caso."], "kw": "menisco, legamento crociato anteriore, radice del menisco, ginocchio"}, "2": {"prof": ["Tunnel femorale nel LCA: con il quadricipite meno anteriore che con il rotuleo", "Serie retrospettiva di Pittsburgh (J Exp Orthop, 2026; 372 LCA primari con metodo dei quadranti): quartile più anteriore con rotuleo 38% contro 22% e quadricipite 29% contro 50% (p=0,002 per entrambi); quartile più prossimale con tacca a 'A' 53% contro 39% (p=0,016), condilo laterale più piccolo (30,4 contro 31,3 mm; p=0,048) e sesso femminile (probabilità 1,9 volte).", "Nota critica: livello IV, nessun esito clinico, tecnica di perforazione non riportata nell'abstract."], "mix": ["Dove cade il tunnel del femore nel crociato: dipende dall'innesto e dall'anatomia", "In una serie di 372 ricostruzioni del legamento crociato anteriore, il tunnel sul femore risultava più avanti con il tendine rotuleo (38% dei casi nel gruppo più anteriore contro 22%) e meno con il tendine del quadricipite (29% contro 50%); risultava più in alto quando la tacca del femore ha forma di 'A', il condilo è piccolo e nelle donne.", "Nota sul limite: lo studio misura dove cade il tunnel, non se il risultato clinico cambi."], "paz": ["Crociato: la posizione del tunnel nel femore cambia con il tendine usato e con l'anatomia", "In uno studio su 372 persone operate al legamento crociato anteriore, il foro nell'osso della coscia tendeva a trovarsi più avanti quando si usava il tendine della rotula e più in alto in chi ha un incavo del femore a forma di 'A', un osso più piccolo e nelle donne.", "Lo studio non dice se la posizione del foro cambi il risultato: è un'osservazione sul passato."], "kw": "legamento crociato anteriore, tendine quadricipitale, tunnel femorale, ginocchio"}, "3": {"prof": ["Radice mediale: centralizzazione e sutura nel coniglio, meno danno cartilagineo, estrusione invariata", "Studio controllato su 16 conigli (Am J Sports Med, 2026; ancore senza nodi, sutura da sola contro con centralizzazione, 4 mesi): degenerazione macroscopica 12,3 ± 2,2 contro 9,1 ± 2,0 (p=0,01), OARSI 4,2 ± 1,5 contro 3,1 ± 1,6 (p=0,04), guarigione migliore con la centralizzazione (p=0,041), estrusione senza differenza (p=0,12).", "Nota critica: modello animale, 8 per braccio; non prova effetti nell'uomo e l'estrusione non cambia."], "mix": ["Radice del menisco: aggiungere la centralizzazione alla sutura, un segnale dal coniglio", "In sedici conigli con rottura dell'attacco posteriore del menisco interno, la sutura associata a una tecnica che riporta il menisco verso l'interno dell'articolazione ha dato dopo quattro mesi meno danno alla cartilagine e una guarigione migliore rispetto alla sola sutura; la sporgenza del menisco non è cambiata in modo evidente.", "Nota sul limite: è uno studio sull'animale, con pochi esemplari; servono studi sull'uomo."], "paz": ["Menisco: uno studio sull'animale sulla sutura con un passaggio in più", "In uno studio su sedici conigli, riparare l'attacco posteriore del menisco interno aggiungendo una tecnica che sposta il menisco verso l'interno ha dato, dopo quattro mesi, meno danni alla cartilagine rispetto alla sola sutura.", "Lo studio riguarda animali e non dice come andrebbe una persona: è un primo passo per ricerche future."], "kw": "menisco, radice del menisco, sutura, cartilagine"}, "4": {"prof": ["Varismo e angolo posterolaterale: nel cadavere 8° di varo aumentano il carico sul LCA, la ricostruzione lo normalizza", "Studio su cadavere (KSSTA, 2026; 8 ginocchia, 0-40° di flessione, 200 N): con PLC integro forza sul LCA da 77,1 ± 7,3 N (neutro, 20°) a 109,9 ± 46,8 N (8° di varo, 40°); dopo sezione del PLC da 80,0 ± 12,3 a 153,2 ± 58,4 N (p<0,001); dopo ricostruzione secondo Arciero nessun effetto significativo (p>0,05).", "Nota critica: 8 ginocchia con deviazioni standard fino a 58 N; LCA nativo e non innesto; la mancanza di effetto non prova equivalenza."], "mix": ["Gambe a O e legamento crociato: l'angolo posterolaterale pesa sul carico", "In un esperimento su otto ginocchia di cadavere, un asse a O (varo) di 8 gradi ha aumentato il carico sul legamento crociato anteriore a flessioni intermedie; con la parte esterna e posteriore del ginocchio (angolo posterolaterale) lesionata l'aumento era molto maggiore, e dopo la ricostruzione di questa struttura l'effetto non era più significativo.", "Nota sul limite: pochi cadaveri e carico quasi fermo; non sono pazienti."], "paz": ["Gambe ad arco e crociato: il lato esterno del ginocchio conta nel carico sul legamento", "In un esperimento di laboratorio su otto ginocchia di cadavere, una gamba ad arco di 8 gradi caricava di più il legamento crociato anteriore; se il lato esterno e posteriore del ginocchio era lesionato il carico saliva molto di più, e ricostruendolo l'aumento non era più rilevabile.", "Lo studio non riguarda persone operate: indica una direzione di ricerca, non una scelta di cura."], "kw": "legamento crociato anteriore, angolo posterolaterale, varismo, ginocchio"}, "5": {"prof": ["Osteotomia tibiale alta a V rovesciata: la degenerazione rotulea predice sintomi peggiori a 2 anni", "Coorte retrospettiva di Sapporo (J Exp Orthop, 2026; 46 ginocchia, 55,5 ± 8,3 anni): KOOS e Lysholm migliorano a 2 anni, ma il WORMS della cartilagine rotulea predice in modo indipendente un KOOS Symptoms più basso, mentre il WORMS non correla con il Lysholm; coefficienti e intervalli non riportati nell'abstract.", "Nota critica: retrospettivo, 46 ginocchia, nessun controllo senza osteotomia; osteotomia a V rovesciata."], "mix": ["Osteotomia del ginocchio: la cartilagine della rotula conta per i sintomi dopo 2 anni", "In uno studio su 46 ginocchia operate di osteotomia tibiale alta per correggere l'asse, punteggi e allineamento sono migliorati a 2 anni; ma chi aveva già una cartilagine della rotula più rovinata ha riferito più sintomi, indipendentemente dalle altre condizioni.", "Nota sul limite: lo studio guarda al passato e non ha un gruppo non operato per confronto."], "paz": ["Correggere l'asse del ginocchio: la rotula conta per i fastidi a 2 anni", "In uno studio su 46 ginocchia con intervento per raddrizzare l'asse della gamba, il ginocchio e i punteggi sono migliorati dopo 2 anni, ma chi aveva già la cartilagine della rotula più consumata ha continuato ad avvertire più fastidi.", "Lo studio guarda al passato e non confronta con chi non si è operato: se ne parla con il chirurgo."], "kw": "osteotomia tibiale alta, cartilagine, rotula, ginocchio"}, "6": {"prof": ["LCA con pendenza tibiale ridotta: a 14 anni punteggi più alti con il doppio fascio, associazione piccola", "Studio retrospettivo di Taiwan (Acta Orthop Traumatol Turc, 2026; 136 pazienti con pendenza sotto 7,4°, fascio singolo 64 contro doppio fascio 72, follow-up 14,06 ± 2,98 anni): UCLA 9,32 ± 0,95 contro 8,55 ± 1,99, Lysholm 94,26 ± 5,61 contro 88,23 ± 13,45, IKDC 82,99 ± 4,55 contro 77,67 ± 11,21 (p<0,01 per tutti).", "Nota critica: retrospettivo, assegnazione non descritta, differenze di 5-6 punti con deviazioni standard fino a 13; gli autori invitano alla cautela."], "mix": ["Crociato e pendenza della tibia: dopo 14 anni punteggi un po' più alti con la tecnica a doppio fascio", "In uno studio retrospettivo su 136 pazienti con una pendenza ridotta del piatto tibiale, chi aveva avuto un doppio fascio riferiva dopo circa 14 anni punteggi un po' più alti di chi aveva avuto un fascio singolo; fra gli uomini la differenza non era significativa.", "Nota sul limite: i gruppi non erano assegnati a caso e la differenza è piccola; gli stessi autori la leggono con cautela."], "paz": ["Crociato operato in due modi: dopo 14 anni risultati leggermente diversi in uno studio sul passato", "In uno studio su 136 persone operate al legamento crociato anteriore e con il piatto della tibia poco inclinato, chi era stato operato con la tecnica a due fasci riferiva dopo circa 14 anni punteggi un po' più alti di chi era stato operato con un fascio solo.", "Lo studio guarda al passato e la differenza è piccola: non indica che una tecnica sia da preferire per chiunque."], "kw": "legamento crociato anteriore, doppio fascio, pendenza tibiale, ginocchio"}, "7": {"prof": ["Osteotomia tibiale alta di apertura: pianificazione automatica con intelligenza artificiale in 25 secondi", "Sviluppo e validazione multicentrica (KSSTA, 2026; 594 pazienti, 136 test e 100 esterni): accuratezza dello spazio di osteotomia 0,53 ± 0,63 mm contro 0,46-0,50 mm di tre chirurghi, accettabile in 98,1% contro 93,6-96,0%; tempo 25,3 ± 0,8 contro 148,7 ± 10,1 secondi (p<0,001).", "Nota critica: riferimento costruito da esperti, nessun esito clinico, solo piano coronale senza slope."], "mix": ["Pianificare un'osteotomia del ginocchio con l'intelligenza artificiale: stessa precisione degli esperti, più rapido", "Un sistema di intelligenza artificiale addestrato su 594 radiografie ha pianificato da solo l'osteotomia tibiale alta di apertura con una precisione simile a quella di tre chirurghi esperti e con un tempo di circa 25 secondi invece di circa 149.", "Nota sul limite: il sistema è stato confrontato con misure di esperti e non con gli esiti dei pazienti; non considera la pendenza della tibia."], "paz": ["Un programma che aiuta a pianificare l'intervento di raddrizzamento della gamba", "Un programma di intelligenza artificiale ha pianificato su radiografie di 594 pazienti l'intervento che corregge l'asse del ginocchio, con una precisione simile a quella dei chirurghi esperti e in pochi secondi.", "Il programma aiuta il chirurgo a preparare l'intervento e non sostituisce la sua decisione; lo studio non misura gli esiti dei pazienti."], "kw": "osteotomia tibiale alta, pianificazione, intelligenza artificiale, ginocchio"}, "8": {"prof": ["Monocompartimentale contro totale oltre i 75 anni: meno complicanze e più soddisfazione a 24-36 mesi", "Coorte retrospettiva con propensity matching (J Robot Surg, 2026; 60 UKA e 120 TKA, almeno 75 anni): complicanze 3/60 (5,0%) contro 19/120 (15,8%), differenza −10,8 punti (IC 95% da −19,4 a −2,3; OR aggiustato 0,31, IC 95% 0,09-0,92); soddisfazione 98,3% contro 86,7%; degenza 3,0 contro 5,2 giorni.", "Nota critica: retrospettivo, eventi pochi, risultato sensibile al test; RR grezzo 0,32 (IC 95% 0,10-1,03)."], "mix": ["Protesi parziale o totale oltre i 75 anni: in uno studio, meno complicanze e più soddisfazione con la parziale", "In 180 pazienti di almeno 75 anni con artrosi limitata al lato interno del ginocchio, dopo 24-36 mesi chi aveva avuto la protesi parziale aveva avuto complicanze nel 5,0% dei casi contro il 15,8% con la totale, degenza più breve e soddisfazione del 98,3% contro l'86,7%.", "Nota sul limite: i pazienti non erano assegnati a caso e gli eventi sono pochi; la differenza nelle complicanze dipende dal metodo di calcolo."], "paz": ["Protesi di ginocchio dopo i 75 anni: parziale e totale a confronto in uno studio sul passato", "In 180 pazienti di almeno 75 anni con il solo lato interno del ginocchio consumato, chi aveva avuto la protesi parziale è stato in ospedale meno giorni e dopo due o tre anni si dichiarava soddisfatto più spesso di chi aveva avuto la protesi totale.", "Lo studio guarda al passato e i pazienti erano scelti per il tipo di protesi: non indica quale sia adatta a una singola persona."], "kw": "protesi monocompartimentale, protesi totale di ginocchio, anziani, artrosi"}, "9": {"prof": ["TKA robotica con CORI: il tensionatore digitale dà gap laterali maggiori e mediali minori del manuale", "Coorte prospettica (KSSTA, 2026; 152 TKA con CORI): gap laterale in estensione 2,38 contro 1,63 mm con il tensionatore digitale (100 N medialmente, 50 N lateralmente) rispetto alla tecnica manuale (p<0,001); gap mediale −0,92 contro −0,00 mm in estensione e 0,79 contro 1,19 mm a 100° (p<0,001).", "Nota critica: misura due tecniche e non gli esiti; forze diverse fra i lati; sistema CORI, non VELYS."], "mix": ["Protesi di ginocchio robotica: misurare gli spazi con uno strumento digitale o a mano dà valori diversi", "In 152 interventi di protesi totale con un sistema robotico, lo strumento digitale che tende i tessuti con una forza nota ha misurato uno spazio laterale più ampio e uno spazio mediale più stretto rispetto alla misura fatta a mano dal chirurgo; le differenze erano costanti.", "Nota sul limite: lo studio non misura gli esiti per il paziente; confronta soltanto due modi di misurare."], "paz": ["Protesi di ginocchio con il robot: due modi di misurare gli spazi danno numeri diversi", "Durante 152 interventi di protesi di ginocchio con l'aiuto di un robot, uno strumento digitale e la misura a mano hanno dato valori diversi per lo spazio fra le ossa, più ampio all'esterno e più stretto all'interno con lo strumento digitale.", "Lo studio non dice come stiano i pazienti dopo l'intervento: descrive come si misura durante l'operazione."], "kw": "protesi di ginocchio, chirurgia robotica, bilanciamento, ginocchio"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"green",sec:"res",j:"J Exp Orthop",h:"Radice laterale con il LCA: tunnel tibiale condiviso o separato, esiti simili a 2 anni e circa 24 minuti in meno",v:"Coorte retrospettiva di un solo chirurgo (Chennai) su 50 LCA con hamstring e sutura transtibiale della radice posteriore del menisco laterale: 24 con il tunnel tibiale del LCA condiviso, 26 con tunnel separato. Tempo operatorio 73,50 ± 8,51 contro 97,00 ± 8,39 minuti (p<0,001); a 2 anni Lysholm 91,50 ± 3,01 contro 91,35 ± 3,03 (p=0,858) e IKDC 90,52 ± 2,72 contro 89,67 ± 3,07; guarigione della radice alla RM sovrapponibile (p=0,231), ma completa in 16/24 contro 21/26.",ax:"Balashanmugam, Kasthuriranganathan, Murali, Ravi, Perumal, Sivaraman",date:"mar 2026",meta:"coorte retrospettiva comparativa, livello III, 50 pazienti (24 contro 26), follow-up minimo 2 anni",pmid:'42898998',doi:'10.1002/jeo2.70687',journal:"Journal of experimental orthopaedics",authors:"Balashanmugam AN, Kasthuriranganathan SA, Murali V, Ravi P, Perumal S, Sivaraman A",design:"Studio retrospettivo comparativo monocentrico (Sri Ramachandra, Chennai; giugno 2019-giugno 2022), un solo chirurgo: 78 pazienti identificati, 50 inclusi (maturi scheletricamente, LCA con semitendinoso e gracile, rifissazione della radice posteriore laterale, almeno 2 anni; esclusi PCL, collaterali, condropatia oltre il grado II, revisioni, deformità da osteotomia). Gruppo 1 (24): suture della radice passate nel tunnel tibiale del LCA, fissate con la stessa vite a interferenza posta davanti all'innesto, senza fissazione extracorticale. Gruppo 2 (26): tunnel separato da 4,5 mm con guida a 60° e fissazione extracorticale. Lachman, pivot shift, IKDC, Lysholm; RM a 2 anni (guarigione in 3 gradi, estrusione laterale) letta in cieco da due radiologi. Letto il testo completo (PMC).",pop:"50 pazienti, 78% uomini; età 26,5 ± 4,8 contro 28,7 ± 7,0 anni; innesto 8,2 ± 0,4 mm in tutti; intervallo fra trauma e intervento mediano 5 contro 4,5 mesi. Follow-up minimo 24 mesi, completato da tutti.",results:"Tempo operatorio 73,50 ± 8,51 contro 97,00 ± 8,39 minuti (p<0,001). A 2 anni Lysholm 91,50 ± 3,01 contro 91,35 ± 3,03 (p=0,858), IKDC 90,52 ± 2,72 contro 89,67 ± 3,07; Lachman 0 in 23/24 contro 24/26 e pivot shift 0 in 23/24 contro 25/26. Guarigione della radice alla RM: completa 16/24 (66,7%) contro 21/26 (80,8%), parziale 8 contro 4, mancata 0 contro 1 (p=0,231). Estrusione laterale da 3,38 ± 0,13 a 1,24 ± 0,28 mm contro 3,49 ± 0,18 a 1,48 ± 0,25 mm; riduzione 2,14 ± 0,35 contro 2,01 ± 0,35 mm (p=0,181; IC 95% della differenza −0,064/+0,334). Ritorno al livello di prima 21/24 contro 23/26 (p=0,91). Nessuna complicanza, nessuna revisione.",concl:"Gli autori: il tunnel tibiale condiviso dà esiti clinici, riferiti e alla RM paragonabili al tunnel separato con un tempo operatorio più breve, risparmia osso e un impianto ed evita la convergenza dei tunnel; lo raccomandano come opzione sicura ed efficiente insieme al LCA.",limits:"Retrospettivo, un solo chirurgo, 50 su 78 pazienti inclusi · i gruppi hanno 24 e 26 pazienti: 'comparabile' non è equivalenza (guarigione non completa 8/24 contro 5/26, RR 1,73; IC 95% 0,66-4,57, potenza.py) · l'uscita delle suture nel tunnel del LCA è 5-6 mm davanti alla radice anatomica e le conseguenze biomeccaniche non sono state misurate · tipi di lesione della radice non sottoclassificati, nessun second look · stima di potenza calcolata a posteriori su una differenza IKDC di 8 punti.",perte:"Verde: tocca due tuoi gesti, il LCA e la rifissazione transtibiale della radice meniscale, ma con un costrutto diverso. La radice è la laterale (la tua tecnica dichiarata riguarda la mediale), l'innesto è semitendinoso e gracile e non il tuo retto femorale o quadricipite, e la plastica laterale non è descritta: non direttamente trasferibile. Il dato utile è che la sutura passata nel tunnel del LCA non peggiora gli esiti a 2 anni e fa risparmiare un tunnel in un'area dove i due tunnel si avvicinano. Non muove le tensioni in modo sostanziale (l'estrusione si riduce in entrambi i gruppi, T3). Cosa fare: nulla da cambiare; come informazione, se dovessi associare una rifissazione laterale a un LCA, la via del tunnel condiviso ha un'evidenza retrospettiva a suo favore."},{n:2,mono:"m-jeo",dot:"green",sec:"res",j:"J Exp Orthop",h:"Tunnel femorale nel LCA: con il quadricipite meno anteriore che con il rotuleo; tacca a 'A' e sesso femminile lo spostano in alto",v:"Serie di 372 LCA primari consecutivi del gruppo di Pittsburgh (Musahl) con il metodo dei quadranti: nel quartile più anteriore il rotuleo è presente nel 38% contro il 22% e il quadricipite nel 29% contro il 50% (p=0,002 per entrambi); nel quartile più prossimale la tacca a 'A' è presente nel 53% contro il 39% (p=0,016), il diametro del condilo laterale è minore (30,4 contro 31,3 mm; p=0,048) e le donne hanno 1,9 volte le probabilità di un tunnel prossimale (intervallo non riportato nell'abstract).",ax:"Dadoo, Nukuto, Konstantinou, Inoue, Hartline, Hughes, Irrgang, Musahl",date:"mar 2026",meta:"serie di casi retrospettiva, livello IV, 372 LCA primari consecutivi (2017-2021)",pmid:'42899268',doi:'10.1002/jeo2.70694',journal:"Journal of experimental orthopaedics",authors:"Dadoo S, Nukuto K, Konstantinou E, Inoue J, Hartline J, Hughes JD, Irrgang JJ, Musahl V",design:"Revisione retrospettiva di tutti i LCA primari consecutivi 2017-2021 di un centro (UPMC Freddie Fu Sports Medicine Center, Pittsburgh). Posizione del tunnel femorale misurata con il metodo dei quadranti nelle direzioni posteriore-anteriore e prossimale-distale; si confrontano il quartile più anteriore e quello più prossimale con il resto della coorte per tipo di innesto, larghezza e forma della tacca, larghezza del LCP e diametro del condilo laterale. Letto solo l'abstract.",pop:"372 pazienti, età media 25 anni, 190 (51%) donne. Distribuzione completa degli innesti, tecnica di perforazione del tunnel femorale e risultati clinici non riportati nell'abstract.",results:"Quartile più anteriore contro resto: rotuleo 38% contro 22% (p=0,002), quadricipite 29% contro 50% (p=0,002). Quartile più prossimale contro resto: tacca a 'A' 53% contro 39% (p=0,016); diametro del condilo laterale 30,4 contro 31,3 mm (p=0,048); sesso femminile con probabilità 1,9 volte maggiore di un tunnel prossimale (intervallo di confidenza non riportato nell'abstract).",concl:"Gli autori: il rotuleo si associa a un tunnel femorale più anteriore; la tacca a 'A', il condilo laterale più piccolo e il sesso femminile a uno più prossimale; i dati possono aiutare a prevedere dove cade il tunnel.",limits:"Livello IV, retrospettivo, solo associazioni con quartili estremi · nessun esito clinico: la posizione del tunnel non è collegata qui a rotture, stabilità o punteggi · la tecnica di perforazione (portale, guida) non è nell'abstract e può spiegare parte della differenza · testo completo non letto.",perte:"Verde: tocca il tuo innesto di default. Il dato che ti riguarda è che il quadricipite si associa a un tunnel femorale meno anteriore del rotuleo; con il retto femorale non c'è un dato separato nell'abstract. Non dice se un tunnel più anteriore o prossimale peggiori l'esito. Non muove le tensioni. Cosa fare: nulla da cambiare; come promemoria tecnico, nelle donne e con tacca a 'A' o condilo piccolo il tunnel tende a salire."},{n:3,mono:"m-gray",dot:"green",sec:"res",j:"Am J Sports Med",h:"Radice mediale: la centralizzazione aggiunta alla sutura riduce il danno cartilagineo nel coniglio, ma non l'estrusione",v:"Studio controllato di laboratorio su 16 conigli (Barcellona e Chicago, con Cole, LaPrade e Chahla): rottura della radice posteriore mediale riparata con ancore senza nodi da sola (8) o con centralizzazione (8). A 4 mesi punteggio macroscopico di degenerazione 12,3 ± 2,2 contro 9,1 ± 2,0 (p=0,01), OARSI 4,2 ± 1,5 contro 3,1 ± 1,6 (p=0,04), guarigione della riparazione migliore con la centralizzazione (p=0,041); estrusione senza differenza (p=0,12).",ax:"Dzidzishvili, Nelson, Santangelo, Sikes, Burton, Del Águila López-Pintor, Fernández-Valle, Goodrich, Cole, LaPrade, Chahla",date:"ott 2026",meta:"studio di laboratorio controllato in vivo, 16 conigli (8 contro 8), 4 mesi",pmid:'42899379',doi:'10.1177/03635465261492230',journal:"The American journal of sports medicine",authors:"Dzidzishvili L, Nelson B, Santangelo K, Sikes KJ, Burton L, Del Águila López-Pintor Ó, Fernández-Valle ME, Goodrich L, Cole BJ, LaPrade RF, Chahla J",design:"Modello in vivo nel ginocchio di coniglio: rottura indotta della radice posteriore del menisco mediale in 16 animali; 8 riparati con ancore senza nodi interbloccanti (RR) e 8 con la stessa riparazione più centralizzazione (RR-CP); gli arti controlaterali fungono da controllo. A 4 mesi cartilagine valutata a occhio nudo e al microscopio (OARSI), tessuto di riparazione, spessore della cartilagine ed estrusione con RM a 9,4 T in tre zone del condilo mediale. Letto solo l'abstract.",pop:"16 conigli bianchi della Nuova Zelanda; 8 per braccio; tecnica con ancore senza nodi (non il pull-out transtibiale).",results:"Degenerazione macroscopica 12,3 ± 2,2 con RR contro 9,1 ± 2,0 con RR-CP (p=0,01); OARSI 4,2 ± 1,5 contro 3,1 ± 1,6 (p=0,04); punteggio di guarigione della riparazione 1,75 ± 0,5 e 2,5 ± 0,7 (p=0,041), a favore di RR-CP (ordine dei gruppi e direzione della scala non precisati nell'abstract), con più riparazioni non guarite in RR (conteggi non riportati nell'abstract). Alla RM spessore della cartilagine centrale e posteriore ridotto con RR rispetto a RR-CP e controlli (p≤0,02), non anteriormente (p=0,23). Estrusione senza differenza (p=0,12). Entrambi i gruppi con più danno cartilagineo dei controlli (p<0,001).",concl:"Gli autori: la centralizzazione associata alla riparazione della radice si associa a meno danno cartilagineo e a una migliore guarigione, senza differenza nell'estrusione; fornisce una base per studi clinici che definiscano indicazioni e selezione dei pazienti.",limits:"Modello animale, 8 conigli per braccio: nessuna conclusione sull'uomo · l'estrusione, il bersaglio della tensione, non cambia (p=0,12) con otto animali per gruppo · ancore senza nodi e non pull-out transtibiale · anche il gruppo con centralizzazione ha più danno dei controlli (p<0,001) · testo completo non letto.",perte:"Verde: tocca la tua rifissazione della radice mediale, ma è un animale e usa ancore, non il tuo tunnel transtibiale. È il primo dato controllato sulla centralizzazione aggiuntiva che la tensione T3 cerca come studio chiarificatore, e dà un segnale a favore sulla cartilagine ma non sull'estrusione. Muove la tensione T3 di poco: nessun cambiamento di azione. Cosa fare: nulla da cambiare; da tenere come ipotesi biologica finché non c'è un trial sull'uomo."},{n:4,mono:"m-kssta",dot:"green",sec:"res",j:"KSSTA",h:"Varismo e angolo posterolaterale: nel cadavere 8° di varo caricano di più il LCA, e senza PLC l'aumento è maggiore",v:"Studio biomeccanico su 8 ginocchia di cadavere (Kiel e Münster, Kittl ultimo autore), 0-40° di flessione e carico assiale di 200 N: con il PLC integro la forza sul LCA va da 77,1 ± 7,3 N (assetto neutro, 20°) a 109,9 ± 46,8 N (8° di varo, 40°); dopo sezione del PLC passa da 80,0 ± 12,3 a 153,2 ± 58,4 N (p<0,001); dopo la ricostruzione secondo Arciero non emergono effetti significativi del varo (p>0,05).",ax:"Gellhaus, Deichsel, Stening, Albert, Peez, Behrendt, Seekamp, Raschke, Horst, Kittl",date:"ott 2026",meta:"studio biomeccanico su cadavere, 8 ginocchia, 5 angoli di flessione, 4 gradi di varo",pmid:'42897444',doi:'10.1002/ksa.70654',journal:"Knee surgery, sports traumatology, arthroscopy : official journal of the ESSKA",authors:"Gellhaus F, Deichsel A, Stening J, Albert A, Peez C, Behrendt P, Seekamp A, Raschke MJ, Horst K, Kittl C",design:"Otto ginocchia di cadavere (età media 62 ± 12 anni) in una macchina di prova con montaggio a cinque gradi di libertà, flessione 0-40° con 200 N di carico assiale; LCA staccato dalla tibia e rifissato con 80 N e tensionatore. Varismo di 0°, 3°, 5° e 8° ottenuto con osteotomia femorale distale di apertura laterale con fissatore esterno e cunei stampati in 3D. Tre condizioni: nativo, sezione del PLC (collaterale laterale e popliteo), ricostruzione del PLC secondo Arciero. Letto solo l'abstract.",pop:"8 ginocchia di cadavere, età media 62 ± 12 anni; LCA nativo e non un innesto.",results:"Con PLC integro la forza sul LCA va da 77,1 ± 7,3 N (neutro, 20°) a 109,9 ± 46,8 N (8° di varo, 40°); aumenti significativi a 30° (p=0,006) e 40° (p=0,001) con 8° di varo. Dopo sezione del PLC aumenti significativi già da 5° di varo e da 10° di flessione, con 80,0 ± 12,3 N (neutro) contro 153,2 ± 58,4 N (8°, 40°; p<0,001). Dopo ricostruzione del PLC nessun effetto significativo di varo o flessione (p>0,05).",concl:"Gli autori: sotto compressione e spinta in varo, un varismo fino a 5° non aumenta in modo significativo la forza sul LCA con PLC integro, mentre 8° sì; la carenza del PLC amplifica l'effetto, che la ricostruzione elimina.",limits:"Cadavere, 8 ginocchia: la mancanza di effetto dopo la ricostruzione non è prova di equivalenza e con deviazioni standard fino a 58 N non esclude differenze moderate · LCA nativo staccato e rifissato a 80 N, non un innesto · carico quasi statico e non attività reale · solo flessione fino a 40°.",perte:"Verde: tocca due tuoi ambiti, l'osteotomia correttiva e la protezione del LCA, ma è biomeccanica su cadavere. Il messaggio utile è che il varismo da solo pesa poco sul LCA fino a 5° e molto di più con l'angolo posterolaterale insufficiente; non riguarda il LET e non dice nulla sull'innesto quadricipitale. Non muove le tensioni. Cosa fare: nulla da cambiare; come ipotesi, in un LCA con varismo marcato e PLC lasso valutare l'angolo posterolaterale prima di proteggere l'innesto."},{n:5,mono:"m-gray",dot:"green",sec:"res",j:"J Exp Orthop",h:"Osteotomia tibiale alta a V rovesciata: la cartilagine rotulea degenerata predice sintomi peggiori a 2 anni",v:"Coorte retrospettiva di Sapporo su 46 ginocchia (39 pazienti, 55,5 ± 8,3 anni) con osteotomia tibiale alta a V rovesciata: KOOS e Lysholm migliorano a 2 anni, ma il sottopunteggio WORMS della cartilagine rotulea resta, dopo aggiustamento, un predittore indipendente di KOOS Symptoms più bassi (coefficienti e intervalli non riportati nell'abstract); il WORMS non correla con il Lysholm.",ax:"Jo, Sato, Ebata, Hosokawa, Hara, Iwasaki, Matsuoka, Onodera, Kondo, Iwasaki",date:"mar 2026",meta:"coorte retrospettiva, livello IV, 46 ginocchia, follow-up 2 anni",pmid:'42899002',doi:'10.1002/jeo2.70690',journal:"Journal of experimental orthopaedics",authors:"Jo Y, Sato D, Ebata T, Hosokawa Y, Hara M, Iwasaki K, Matsuoka M, Onodera T, Kondo E, Iwasaki N",design:"Revisione retrospettiva (Hokkaido University; 2015-2022) di osteotomie tibiali alte a V rovesciata con RM preoperatoria e follow-up a 2 anni. Punteggi WORMS per cartilagine, menisco, edema osseo, cisti ed effusione per compartimento; confronti pre-post con test t per dati appaiati, correlazioni di Spearman con KOOS e Lysholm, regressione lineare multivariata sul KOOS Symptoms a 2 anni con WORMS rotuleo, sintomi preoperatori, età, BMI e WORMS del condilo femorale mediale. Letto solo l'abstract.",pop:"46 ginocchia, 39 pazienti; età 55,5 ± 8,3 anni; BMI 27,9 ± 4,0 kg/m².",results:"Lysholm e KOOS migliorano in modo significativo dal basale a 2 anni; angolo anca-ginocchio-caviglia, linea di carico, angolo femorotibiale e angolo prossimale mediale della tibia cambiano in modo significativo, mentre gli indici di altezza della rotula restano invariati. Nessuna correlazione significativa fra WORMS e Lysholm. Il sottopunteggio della cartilagine correla negativamente con il KOOS Symptoms, più forte alla rotula, poi al condilo femorale mediale; nel modello aggiustato il WORMS rotuleo predice in modo indipendente un KOOS Symptoms più basso, gli altri fattori no. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: l'osteotomia migliora gli esiti a 2 anni, ma una degenerazione rotulea preoperatoria avanzata si associa a sintomi peggiori nonostante il riallineamento; la stadiazione femororotulea dovrebbe guidare indicazione, colloquio e pianificazione.",limits:"Retrospettivo e monocentrico, 46 ginocchia · modello aggiustato con 5 variabili su 46 ginocchia di 39 pazienti (le ginocchia bilaterali non sono indipendenti) · nessun gruppo di controllo senza osteotomia, quindi non si sa se i sintomi sarebbero comunque peggiori · osteotomia a V rovesciata, non necessariamente la tua tecnica · testo completo non letto.",perte:"Verde: tocca la tua osteotomia correttiva. Segnala che la cartilagine rotulea conta nelle aspettative e nell'indicazione, in parziale tensione con un editoriale di ieri (PMID 42837200) che sosteneva che l'artrosi femororotulea non controindichi l'osteotomia di apertura. Non muove le tensioni. Cosa fare: nulla da cambiare; come elemento di colloquio, stadiare la rotula in RM prima di un'osteotomia."},{n:6,mono:"m-gray",dot:"green",sec:"res",j:"Acta Orthop Traumatol Turc",h:"LCA con pendenza tibiale laterale ridotta: a 14 anni il doppio fascio ha punteggi più alti del fascio singolo",v:"Studio retrospettivo comparativo di Taiwan (Chang Gung) su 136 pazienti con pendenza tibiale laterale sotto 7,4°, fascio singolo (64) contro doppio fascio (72), follow-up medio 14,06 ± 2,98 anni: UCLA 9,32 ± 0,95 contro 8,55 ± 1,99 (p<0,01), Lysholm 94,26 ± 5,61 contro 88,23 ± 13,45 (p<0,01), IKDC 82,99 ± 4,55 contro 77,67 ± 11,21 (p<0,01); fra gli uomini nessuna differenza significativa. Intervalli di confidenza non riportati nell'abstract.",ax:"Yao, Lin, Chan, Hung, Hung, Chen, Chiu, Ho, Yang",date:"set 2026",meta:"studio retrospettivo comparativo, 136 pazienti (64 contro 72), follow-up medio 14 anni",pmid:'42897826',doi:'10.5152/j.aott.2026.25795',journal:"Acta orthopaedica et traumatologica turcica",authors:"Yao SY, Lin KY, Chan YS, Hung YC, Hung SF, Chen YJ, Chiu CH, Ho CS, Yang CP",design:"Studio retrospettivo comparativo monocentrico di LCA con fascio singolo o doppio fascio in pazienti con pendenza tibiale laterale ridotta (< 7,4°, misurata sulla RM preoperatoria). Esiti riferiti (UCLA, Lysholm, IKDC) a un follow-up medio di 14 anni, confrontati con test chi quadrato e t per campioni indipendenti. Tipo di innesto e criterio di assegnazione al gruppo non riportati nell'abstract. Letto solo l'abstract.",pop:"136 pazienti, 64 fascio singolo e 72 doppio fascio; pendenza tibiale laterale 4,76 ± 1,48° contro 4,23 ± 1,82° (p=0,06); follow-up medio 14,06 ± 2,98 anni.",results:"UCLA 9,32 ± 0,95 con il doppio fascio contro 8,55 ± 1,99 (p<0,01); Lysholm 94,26 ± 5,61 contro 88,23 ± 13,45 (p<0,01); IKDC 82,99 ± 4,55 contro 77,67 ± 11,21 (p<0,01). Nei soli uomini nessuna differenza significativa, con tendenza a favore del doppio fascio. Intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: con una pendenza ridotta il doppio fascio si associa a punteggi riferiti più alti a lungo termine; la rilevanza clinica delle differenze va letta con cautela.",limits:"Retrospettivo, assegnazione non randomizzata e non descritta nell'abstract: bias di selezione non escluso · differenze di 5-6 punti con deviazioni standard fino a 13; gli autori stessi invitano alla cautela sulla rilevanza clinica · nessun gruppo con pendenza normale o alta per confronto · nessun dato su rotture, reinterventi o stabilità oggettiva nell'abstract · plastica laterale non menzionata.",perte:"Verde: tocca la pendenza tibiale, uno dei tuoi temi, ma con il doppio fascio, che non è la tua tecnica, e nulla sul LET né sul quadricipite. Non è trasferibile al tuo costrutto. Non muove le tensioni. Cosa fare: nulla da cambiare; come informazione, la pendenza bassa non ha un effetto uniforme sugli esiti a lungo termine, ma l'associazione qui è piccola e retrospettiva."},{n:7,mono:"m-kssta",dot:"gray",sec:"res",j:"KSSTA",h:"Osteotomia tibiale alta di apertura: un sistema di intelligenza artificiale pianifica sulla radiografia in 25 secondi invece di 149",v:"Sviluppo e validazione multicentrica (Monaco di Baviera, premio ISAKOS John Joyce 2025) di una rete profonda che pianifica da sola l'osteotomia tibiale alta mediale di apertura sulla radiografia lunga in carico: 594 pazienti, 136 di test e 100 esterni. Accuratezza dello spazio di osteotomia 0,53 ± 0,63 mm contro 0,46-0,50 mm dei tre chirurghi esperti, accettabile clinicamente in 98,1% contro 93,6-96,0%; tempo 25,3 ± 0,8 contro 148,7 ± 10,1 secondi (p<0,001).",ax:"Rupp, von Schacky, Lindner, Feucht, Ehmann, Fritsch, Doucas, Haddadin, Hinterwimmer, Jung, Russe, von Eisenhart-Rothe, Siebenlist, Wilhelm",date:"ott 2026",meta:"sviluppo e validazione retrospettiva, livello III, 594 pazienti, due istituzioni più test esterno",pmid:'42897441',doi:'10.1002/ksa.70635',journal:"Knee surgery, sports traumatology, arthroscopy : official journal of the ESSKA",authors:"Rupp MC, von Schacky CE, Lindner FJ, Feucht MJ, Ehmann Y, Fritsch L, Doucas A, Haddadin S, Hinterwimmer F, Jung M, Russe MF, von Eisenhart-Rothe R, Siebenlist S, Wilhelm NJ",design:"Studio retrospettivo di sviluppo e validazione di un sistema di apprendimento profondo (dodici reti esperte per i punti di repere) per la pianificazione completamente automatica di un'osteotomia tibiale alta mediale di apertura su radiografia anteroposteriore lunga in carico, con due obiettivi (intersezione dell'asse meccanico con il piatto in percentuale, oppure asse femorotibiale in gradi). 594 pazienti operati di osteotomia 2014-2021, divisi in addestramento (399), validazione (59) e test (136), più 100 esterni. Confronto con tre chirurghi che usano un software approvato dalla FDA. Letto solo l'abstract.",pop:"594 pazienti, età 41,1 ± 13,2 anni, 182 donne; test 136 e test esterno 100.",results:"Accuratezza dei parametri preoperatori: modello da 0,22 ± 0,18 a 1,04 ± 1,28°, chirurghi da 0,13 ± 0,10 a 1,06 ± 1,4°; accettabile in 91-100% contro 72-100%. Spazio di osteotomia: modello 0,53 ± 0,63 mm (obiettivo percentuale) e 0,44 ± 0,53 mm (obiettivo in gradi), chirurghi 0,46 ± 0,65 - 0,5 ± 0,88 mm e 0,43 ± 0,55 - 0,52 ± 0,75 mm; accettabile in 98,1% e 96,2% contro 93,6-96,0% e 89,8-93,9%. Affidabilità intraosservatore 1,0 contro 0,88. Tempo di analisi 25,3 ± 0,8 contro 148,7 ± 10,1 secondi (p<0,001).",concl:"Gli autori: il sistema pianifica in modo autonomo con affidabilità pari a quella degli esperti, riducendo il tempo e migliorando la coerenza delle misure; potrebbe assistere e standardizzare la pianificazione.",limits:"Retrospettivo: confronta con un riferimento costruito da esperti, non con l'esito clinico dei pazienti · due istituzioni e solo radiografie anteroposteriori; non valuta slope né osteotomie diverse dall'apertura mediale · 'accettabile' è una soglia scelta dagli autori · uso reale con il chirurgo nel circuito non testato.",perte:"Grigio: tocca l'osteotomia che pratichi come pianificazione, ma non cambia la tecnica e non ha esiti clinici. Non muove le tensioni. Cosa fare: nulla da cambiare; come promemoria, la pianificazione automatica sta raggiungendo la qualità degli esperti sul solo piano coronale, senza considerare lo slope."},{n:8,mono:"m-jrs",dot:"green",sec:"res",j:"J Robot Surg",h:"Monocompartimentale o totale oltre i 75 anni: a 24-36 mesi complicanze 5,0% contro 15,8% e soddisfazione più alta",v:"Coorte retrospettiva cinese con abbinamento per punteggio di propensione su 180 pazienti di almeno 75 anni con artrosi mediale isolata (60 UKA, 120 TKA): complicanze 3/60 (5,0%) contro 19/120 (15,8%), differenza −10,8 punti (IC 95% da −19,4 a −2,3; OR aggiustato 0,31, IC 95% 0,09-0,92); soddisfazione 98,3% contro 86,7% (+11,7 punti, IC 95% 4,8-18,6); degenza 3,0 contro 5,2 giorni. Il risultato sulle complicanze dipende dal test usato.",ax:"Wang, Fu, Guo, Zhang, Lin, Wang",date:"ott 2026",meta:"coorte retrospettiva con abbinamento per propensity score, 180 pazienti (60 contro 120), follow-up 24-36 mesi",pmid:'42900442',doi:'10.1007/s11701-026-04086-x',journal:"Journal of robotic surgery",authors:"Wang S, Fu Y, Guo Z, Zhang J, Lin C, Wang H",design:"Studio retrospettivo monocentrico di UKA mediale o TKA primarie per artrosi mediale isolata in pazienti di almeno 75 anni (2018-2022): 268 eleggibili (68 UKA, 200 TKA); abbinamento 1:2 per punteggio di propensione con chirurgo, dati demografici, comorbilità, radiografia e funzione basale, con 60 UKA e 120 TKA e differenze standardizzate sotto 0,10. Esiti a 24-36 mesi: KSS, OKS, VAS, mobilità, FJS-12, complicanze, riammissioni, reinterventi, soddisfazione. Se sia stato usato un robot non è riportato nell'abstract. Letto solo l'abstract.",pop:"180 pazienti abbinati, tutti di almeno 75 anni con artrosi isolata del compartimento mediale; 60 UKA e 120 TKA.",results:"Tempo operatorio 64,3 contro 84,2 minuti; perdita ematica 99,9 contro 183,6 mL; calo di emoglobina 1,5 contro 2,6 g/dL; degenza 3,0 contro 5,2 giorni. KSS finale simile; OKS, FJS-12 e flessione più alti e VAS più basso con la UKA. Complicanze 3/60 (5,0%) contro 19/120 (15,8%), differenza −10,8 punti (IC 95% da −19,4 a −2,3), OR aggiustato 0,31 (IC 95% 0,09-0,92). Soddisfazione 98,3% contro 86,7% (+11,7 punti, IC 95% 4,8-18,6). Riammissioni e reinterventi senza differenza chiara (conteggi non riportati nell'abstract).",concl:"Gli autori: in pazienti selezionati di almeno 75 anni la UKA mediale si associa a minore carico perioperatorio ed esiti riferiti più favorevoli rispetto alla TKA a 24-36 mesi; la differenza nelle complicanze va letta con cautela perché gli eventi sono pochi e dipende dal test.",limits:"Retrospettivo con assegnazione non casuale: l'abbinamento corregge solo ciò che è misurato · eventi pochi (3 contro 19); l'RR grezzo delle complicanze è 0,32 con IC 95% 0,10-1,03 (potenza.py), cioè il limite superiore arriva a 1 · indicazioni selettive per la UKA e abbinamento solo sulle variabili misurate · nell'abstract non è detto se fosse usato un robot · testo completo non letto.",perte:"Verde: tocca la tua protesi monocompartimentale. Non è il VELYS né dichiara un robot, e riguarda una popolazione molto anziana e selezionata per la UKA. Va nella direzione di un vantaggio per la UKA in questo gruppo ma non lo dimostra. Non muove le tensioni. Cosa fare: nulla da cambiare; come informazione per il colloquio, nei pazienti oltre i 75 anni con artrosi mediale isolata la UKA ha dati retrospettivi favorevoli."},{n:9,mono:"m-kssta",dot:"gray",sec:"res",j:"KSSTA",h:"TKA robotica con CORI: il tensionatore digitale misura gap laterali maggiori e mediali minori della valutazione manuale",v:"Coorte prospettica (Barcellona-Melbourne) su 152 TKA con il sistema robotico CORI: il tensionatore digitale (100 N mediale, 50 N laterale) misura in estensione un gap laterale maggiore della tecnica manuale con retrattore a Z (2,38 contro 1,63 mm; p<0,001) e gap mediali minori (−0,92 contro −0,00 mm in estensione; 0,79 contro 1,19 mm a 100°; p<0,001), in tutti i sottogruppi di allineamento e di mobilità.",ax:"Borim, Zeng, Lording",date:"ott 2026",meta:"coorte prospettica, livello II, 152 TKA robotiche, misura digitale contro manuale",pmid:'42897440',doi:'10.1002/ksa.70650',journal:"Knee surgery, sports traumatology, arthroscopy : official journal of the ESSKA",authors:"Borim FM, Zeng C, Lording T",design:"Coorte prospettica di 170 TKA primarie con sistema robotico CORI (aprile 2024-marzo 2025), 152 con dati completi; flusso standard con posizione iniziale dell'impianto pianificata in allineamento meccanico neutro. Gap intraoperatori misurati prima con il tensionatore digitale (100 N mediale, 50 N laterale) e poi con la tecnica manuale con retrattore a Z, lungo l'arco di flessione. Letto solo l'abstract.",pop:"152 ginocchia (78 destre, 74 sinistre); allineamento preoperatorio medio 3,72 ± 4,43°; movimento preoperatorio da 6,44 ± 6,06° a 143,34 ± 7,79°.",results:"Gap laterale maggiore con il tensionatore digitale, soprattutto in estensione (0°: 2,38 contro 1,63 mm; p<0,001). Gap mediale minore con il digitale in estensione (−0,92 contro −0,00 mm) e a 100° di flessione (0,79 contro 1,19 mm; p<0,001). Direzione delle differenze mantenuta per allineamento e mobilità preoperatori. Esiti clinici non misurati.",concl:"Gli autori: la misura digitale dà più apertura laterale e meno mediale della manuale; può standardizzare la valutazione, ma il chirurgo deve conoscere le differenze tra tecniche quando interpreta i gap nella pianificazione robotica.",limits:"Misura di due tecniche sullo stesso ginocchio, non di quale dia esiti migliori: nessun esito clinico, nessun follow-up · la forza (100 N e 50 N) è diversa fra i lati e può spiegare parte della differenza · un solo sistema (CORI), un solo software · testo completo non letto.",perte:"Grigio: tocca la protesi robotica, ma con il sistema CORI e non con il VELYS. Non muove le tensioni. Cosa fare: nulla da cambiare; come promemoria, i gap letti con tensionatore digitale non sono sovrapponibili a quelli manuali."}];
var SUGGQ=[{"k": "kol", "n": "Christoph Kittl (Università di Münster, Germania)", "w": "Germania: ultimo autore dello studio sul carico del LCA con varismo e angolo posterolaterale (PMID 42897444; nome e afferenza letti nei metadati PubMed), già comparso in elenchi di coautori nello storico. Corrispondenza tecnica con l'osteotomia correttiva e la protezione del LCA con la ricostruzione dell'angolo posterolaterale, cioè gli ambiti osteotomia e slope che esegui. Sostituisce Daniel B. F. Saris (nessun segnale dell'utente arrivato per farla ruotare)."}];
var BRIEF_TEXT="Mercoledì 21 ottobre. Oggi nove lavori, nessuna scheda rossa e nessuna arancione. Nessun richiamo di dispositivi nuovo rispetto a ieri, nessuna linea guida o consensus nuovo che tocchi la tua pratica e nessuna ritrattazione che ti riguardi. Il lavoro del giorno è uno studio retrospettivo di Chennai, di un solo chirurgo, sulla radice posteriore del menisco laterale riparata durante la ricostruzione del crociato: cinquanta pazienti, ventiquattro con le suture passate nel tunnel tibiale del legamento e ventisei con un tunnel separato, almeno due anni di controllo. Il tempo operatorio è di settantatré virgola cinque contro novantasette minuti, p minore di zero virgola zero zero uno. A due anni il Lysholm è novantuno virgola cinque in entrambi i gruppi, p zero virgola otto cinque otto, e la guarigione completa alla risonanza è in sedici pazienti su ventiquattro contro ventuno su ventisei, p zero virgola due tre uno. Con gruppi così piccoli comparabile non significa equivalente: per la mancata guarigione completa il rischio relativo è uno virgola sette tre, con intervallo di confidenza dal zero virgola sei sei al quattro virgola cinque sette. L'innesto era semitendinoso e gracile, la radice è la laterale e non la tua mediale e nessuna plastica laterale è descritta; ho letto il testo completo. Poi otto lavori. Una serie di trecentosettantadue crociati di Pittsburgh: il tunnel femorale cade meno avanti con il quadricipite che con il rotuleo, ventinove contro cinquanta per cento nel gruppo più anteriore, senza esiti clinici. Un esperimento sul coniglio: la centralizzazione aggiunta alla sutura della radice mediale riduce il danno alla cartilagine ma non l'estrusione, otto animali per gruppo; tocca la tua tensione sulla radice, ma è un animale. Uno studio su cadavere: otto gradi di varo aumentano il carico sul crociato, e di più se l'angolo posterolaterale è insufficiente. Quarantasei osteotomie tibiali alte: una cartilagine rotulea già degenerata predice sintomi peggiori a due anni. Con la pendenza tibiale ridotta, a quattordici anni il doppio fascio ha punteggi più alti del fascio singolo, ma l'associazione è piccola e retrospettiva. Poi tre lavori bianchi o meno vicini: la pianificazione automatica dell'osteotomia con intelligenza artificiale, che arriva alla precisione degli esperti in venticinque secondi; la protesi monocompartimentale contro la totale oltre i settantacinque anni, con meno complicanze ma eventi pochi; e il tensionatore digitale nella protesi robotica CORI, che non è il VELYS. Tensioni: si è mossa di poco quella sulla radice meniscale, con il dato sull'animale.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Mercoledì ventuno ottobre. Nove lavori, nessuna scheda rossa e nessuna arancione. Nessun richiamo nuovo, nessun consensus nuovo sulla tua pratica e nessuna ritrattazione che ti riguardi."}, {"chi": "B", "t": "Qual è il lavoro del giorno?"}, {"chi": "A", "t": "Uno studio retrospettivo di Chennai, di un solo chirurgo, sulla radice posteriore del menisco laterale riparata insieme al crociato. Cinquanta pazienti: ventiquattro con le suture passate nel tunnel tibiale del legamento, ventisei con un tunnel separato."}, {"chi": "B", "t": "E come è andata a due anni?"}, {"chi": "A", "t": "Punteggi e stabilità simili. Il Lysholm è novantuno virgola cinque in entrambi i gruppi. Con il tunnel condiviso l'intervento è più breve di circa ventiquattro minuti: settantatré virgola cinque contro novantasette."}, {"chi": "B", "t": "Il menisco è guarito allo stesso modo?"}, {"chi": "A", "t": "Alla risonanza completamente in sedici pazienti su ventiquattro contro ventuno su ventisei, ma la differenza non è significativa. Con gruppi così piccoli comparabile non vuol dire equivalente: per la mancata guarigione completa il rischio relativo è uno virgola sette tre, con un intervallo che va da zero virgola sei sei a quattro virgola cinque sette."}, {"chi": "B", "t": "Quindi per la tua rifissazione transtibiale della radice cosa cambia?"}, {"chi": "A", "t": "Niente. La radice è la laterale e non la tua mediale, l'innesto è semitendinoso e gracile e non il retto femorale, e nessuna plastica laterale è descritta. È un'informazione, non una correzione."}, {"chi": "B", "t": "Gli altri lavori?"}, {"chi": "A", "t": "Una serie di Pittsburgh su trecentosettantadue crociati: il tunnel femorale cade meno avanti con il quadricipite che con il rotuleo. Poi un esperimento sul coniglio: la centralizzazione aggiunta alla sutura della radice riduce il danno alla cartilagine ma non l'estrusione, con otto animali per gruppo."}, {"chi": "B", "t": "E la tensione sulla radice?"}, {"chi": "A", "t": "Si è mossa di poco: è il primo dato controllato sulla centralizzazione, ma è su un animale. Per l'osteotomia: uno studio su cadavere mostra che otto gradi di varo caricano di più il crociato, e di più se l'angolo posterolaterale è insufficiente; e una cartilagine rotulea degenerata predice sintomi peggiori a due anni dopo l'osteotomia tibiale alta."}, {"chi": "B", "t": "Qualcosa sulla protesi?"}, {"chi": "A", "t": "Tre lavori bianchi o meno vicini: la pianificazione dell'osteotomia con intelligenza artificiale, la monocompartimentale contro la totale oltre i settantacinque anni con meno complicanze ma eventi pochi, e il tensionatore digitale nella protesi robotica CORI, che non è il VELYS."}];
